INSERT INTO `announcements` VALUES (1,'🏷️ 平台正式上线啦！','欢迎来到校园二手交易平台！在这里，你可以自由买卖二手物品，让闲置发挥价值。',1,'2026-04-10 08:10:47','2026-07-09 08:10:47'),(2,'📢 交易须知','请各位用户遵守平台规则，诚信交易。交易前请仔细核对商品信息，建议当面验货。',1,'2026-04-20 08:10:47','2026-07-09 08:10:47'),(3,'🎉 新版功能发布','新增商品收藏、购物车、订单管理等功能，提供更好的交易体验！',1,'2026-05-10 08:10:47','2026-07-09 08:10:47'),(4,'🔒 安全提示','请勿私下交易，谨防诈骗。平台不会以任何理由索要你的密码和验证码。',1,'2026-05-25 08:10:47','2026-07-09 08:10:47'),(5,'📱 APP即将上线','移动端APP正在开发中，敬请期待！',1,'2026-06-09 08:10:47','2026-07-09 08:10:47'),(6,'🎁 暑期活动公告','暑期交易免手续费！欢迎各位同学在暑期进行二手交易！',1,'2026-06-19 08:10:47','2026-07-09 08:10:47'),(7,'📚 开学季特惠','新学期开始，书籍类商品免运费！',1,'2026-06-29 08:10:47','2026-07-09 08:10:47'),(8,'⚡ 系统维护通知','每周三凌晨2:00-4:00进行系统维护，届时可能无法访问，请谅解。',1,'2026-07-04 08:10:47','2026-07-09 08:10:47'),(9,'👮 举报机制上线','如发现违规交易或诈骗行为，可点击\"举报\"按钮，我们将在24小时内处理。',1,'2026-07-06 08:10:47','2026-07-09 08:10:47'),(10,'💡 使用小贴士','发布商品时，建议上传清晰图片，详细描述商品情况，更容易卖出好价格哦！',1,'2026-07-08 08:10:47','2026-07-09 08:10:47');
