INSERT INTO `forum_posts` VALUES (1,2,'大家有没有推荐的二手书店铺？','最近想买几本专业书，不知道有没有靠谱的二手书卖家推荐？','求助',156,1,'2026-06-19 08:11:03','2026-07-09 08:11:03'),(2,3,'今天在平台买到了心仪已久的相机！','终于蹲到了心仪的相机，卖家很nice，成色也很新，开心！','分享',89,1,'2026-06-24 08:11:03','2026-07-09 08:11:03'),(3,4,'二手交易要注意什么？新手求教','第一次用二手平台，有没有什么需要注意的地方？','求助',234,1,'2026-06-27 08:11:03','2026-07-09 08:11:03'),(4,5,'毕业季出清！大量书籍便宜卖','快毕业了，寝室里的书太多了，有需要的同学可以来看看','闲置',345,1,'2026-06-29 08:11:03','2026-07-09 08:11:03'),(5,6,'建议大家交易时一定要当面验货','上次买了个手机，没当面验货，结果屏幕有划痕，很后悔','经验分享',456,1,'2026-07-01 08:11:03','2026-07-09 08:11:03'),(6,7,'有没有人一起拼单买教材？','下学期有几门课需要买教材，有同学一起拼单吗？','求助',67,1,'2026-07-03 08:11:03','2026-07-09 08:11:03'),(7,8,'用了一年多的笔记本还能卖多少钱？','2023款的笔记本，用了快两年了，想换新的，不知道能卖多少','咨询',123,1,'2026-07-05 08:11:03','2026-07-09 08:11:03'),(8,9,'在平台上遇到了非常靠谱的卖家！','态度超级好，还送了不少小礼物，强烈推荐！','推荐',78,1,'2026-07-06 08:11:03','2026-07-09 08:11:03'),(9,10,'闲置护肤品出清','囤货太多了，出一些未开封的护肤品，低价出','闲置',45,1,'2026-07-07 08:11:03','2026-07-09 08:11:03'),(10,2,'建议平台增加一个\"附近交易\"功能','有时候同校交易更方便，希望能加一个筛选同校的功能','建议',234,1,'2026-07-08 08:11:03','2026-07-09 08:11:03');
