DROP TABLE IF EXISTS `news`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `news` (
  `news_id` int NOT NULL AUTO_INCREMENT COMMENT '资讯ID，主键',
  `category_id` int NOT NULL COMMENT '资讯分类ID (news_categories.category_id)',
  `title` varchar(125) NOT NULL COMMENT '资讯标题',
  `summary` varchar(255) DEFAULT NULL COMMENT '资讯摘要',
  `content` longtext NOT NULL COMMENT '资讯内容',
  `cover_img` varchar(255) DEFAULT NULL COMMENT '封面图',
  `hits` int NOT NULL DEFAULT '0' COMMENT '点击量',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态 (1:发布, 0:草稿)',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`news_id`),
  KEY `idx_category_id` (`category_id`),
  CONSTRAINT `fk_news_category_id` FOREIGN KEY (`category_id`) REFERENCES `news_categories` (`category_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='校园资讯表';
/*!40101 SET character_set_client = @saved_cs_client */;

