LOCK TABLES `news` WRITE;
/*!40000 ALTER TABLE `news` DISABLE KEYS */;
INSERT INTO `news` VALUES (1,1,'北京大学二手市场火热开展','北大校园二手市场活动吸引了数千名学生参与，交易额突破10万元。','北京大学校园二手市场活动于本周成功举办，吸引了超过3000名学生参与。活动现场交易火爆，总交易额突破10万元。本次活动不仅促进了闲置物品的循环利用，也为同学们提供了一个交流互动的平台。','https://picsum.photos/seed/news1/800/400',256,1,'2026-06-09 08:11:02','2026-07-09 08:11:02'),(2,2,'二手交易防骗指南','学会这几招，远离二手交易骗局，安全交易不踩坑。','在二手交易中，请务必注意以下防骗要点：1. 核实对方身份，尽量选择实名认证用户交易；2. 优先选择当面交易，仔细验货后再付款；3. 对于贵重物品，建议索要购买凭证或保修卡；4. 不要点击陌生人发送的链接或扫描不明二维码；5. 任何要求提前支付定金的行为都要高度警惕。','https://picsum.photos/seed/news2/800/400',189,1,'2026-06-14 08:11:02','2026-07-09 08:11:02'),(3,3,'平台用户突破10000人','感谢大家的支持！校园二手交易平台用户数已突破10000人。','自平台上线以来，得到了广大师生的热烈支持。截至目前，平台注册用户已突破10000人，累计发布商品超过5000件，完成交易超过3000笔。我们将继续努力，为大家提供更好的服务。','https://picsum.photos/seed/news3/800/400',345,1,'2026-06-19 08:11:02','2026-07-09 08:11:02'),(4,4,'大学生闲置物品交换活动','周末校园闲置物品交换活动，快来参加吧！','本周六下午2点，将在学校图书馆前广场举办闲置物品交换活动。同学们可以带上自己的闲置物品前来交换，书籍、电子产品、生活用品均可参与。活动现场还准备了精美小礼品，欢迎各位同学踊跃参加！','https://picsum.photos/seed/news4/800/400',123,1,'2026-06-24 08:11:02','2026-07-09 08:11:02'),(5,5,'环保与二手交易','选择二手商品，就是选择一种更环保的生活方式。','每购买一件二手商品，就能减少约20kg的碳排放。二手交易不仅能为你的钱包减负，更能为地球减负。让我们从身边小事做起，选择二手商品，践行绿色生活理念，为环境保护贡献一份力量。','https://picsum.photos/seed/news5/800/400',78,1,'2026-06-29 08:11:02','2026-07-09 08:11:02'),(6,1,'清华大学二手集市火爆','清华大学举办的二手集市活动吸引了众多师生参与。','清华大学二手集市于上周末在校园内成功举办，活动持续两天。现场共设有50个摊位，商品种类涵盖书籍、电子产品、生活用品、服饰等各个品类。据统计，活动期间累计交易额超过5万元，参与人数超过2000人。','https://picsum.photos/seed/news6/800/400',234,1,'2026-07-01 08:11:02','2026-07-09 08:11:02'),(7,2,'如何拍出好照片卖出好价格','商品照片拍得好，价格自然卖得高。这些小技巧你一定要知道！','发布商品时，照片是吸引买家注意力的第一要素。拍摄建议：1. 选择光线充足的环境拍摄；2. 保持背景整洁，突出商品主体；3. 从多个角度拍摄，展示商品全貌；4. 对于有瑕疵的地方，建议拍摄特写，坦诚描述更易获得信任；5. 可以添加一些简单的道具，让照片更有生活气息。','https://picsum.photos/seed/news7/800/400',156,1,'2026-07-03 08:11:02','2026-07-09 08:11:02'),(8,3,'平台新增信用评分系统','新版信用评分系统上线，让交易更放心！','为了更好地保障用户权益，平台正式上线信用评分系统。每次交易完成后，买卖双方可以互相评分和评价。信用评分将影响用户在平台的搜索排名和推荐权重。我们希望通过这套系统，激励用户诚信交易，共同营造良好的交易环境。','https://picsum.photos/seed/news8/800/400',89,1,'2026-07-05 08:11:02','2026-07-09 08:11:02'),(9,4,'毕业季二手书大甩卖','毕业季来临，大量优质二手书籍等你来淘！','又是一年毕业季，学长学姐们即将离校，大量优质二手书籍低价出售。教材、教辅、小说、文学名著应有尽有，价格最低1折起。如果你正在寻找心仪的书籍，现在正是最好的时机。赶快来平台搜索你需要的书籍吧！','https://picsum.photos/seed/news9/800/400',267,1,'2026-07-07 08:11:02','2026-07-09 08:11:02'),(10,5,'低碳生活从二手开始','选择二手交易，开启你的低碳生活之旅。','你知道吗？一件衣服的生产过程会产生约20kg的碳排放。而通过购买二手商品，可以有效减少碳排放。二手交易不仅是一种经济实惠的消费方式，更是一种负责任的环保行为。让我们一起行动起来，从选择二手商品开始，为地球减负！','https://picsum.photos/seed/news10/800/400',45,1,'2026-07-08 08:11:02','2026-07-09 08:11:02');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `news_categories`
--

DROP TABLE IF EXISTS `news_categories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `news_categories` (
  `category_id` int NOT NULL AUTO_INCREMENT COMMENT '资讯分类ID，主键',
  `category_name` varchar(64) NOT NULL COMMENT '分类名称',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
