--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `order_id` int NOT NULL AUTO_INCREMENT COMMENT '订单ID，主键',
  `order_number` varchar(64) NOT NULL COMMENT '订单号（唯一）',
  `user_id` int NOT NULL COMMENT '买家ID (users.user_id)',
  `merchant_id` int NOT NULL COMMENT '商家/卖家ID (sellers.seller_id)',
  `goods_id` int NOT NULL COMMENT '商品ID (second_hand_mall.second_hand_mall_id)',
  `title` varchar(125) NOT NULL COMMENT '商品标题（快照）',
  `img` varchar(255) DEFAULT NULL COMMENT '商品图片（快照）',
  `price` decimal(10,2) NOT NULL COMMENT '购买时单价（快照）',
  `price_ago` decimal(10,2) DEFAULT NULL COMMENT '购买时原价（快照）',
  `num` int NOT NULL DEFAULT '1' COMMENT '购买数量',
  `price_count` decimal(10,2) NOT NULL COMMENT '订单总价',
  `norms` varchar(255) DEFAULT NULL COMMENT '规格（快照）',
  `type` varchar(64) NOT NULL DEFAULT '' COMMENT '类型/分类（快照）',
  `description` varchar(255) DEFAULT NULL COMMENT '订单备注',
  `contact_name` varchar(32) NOT NULL COMMENT '收货人姓名（快照）',
  `contact_phone` varchar(13) NOT NULL COMMENT '收货人手机（快照）',
  `contact_address` varchar(255) NOT NULL COMMENT '收货地址（快照）',
  `postal_code` varchar(9) DEFAULT NULL COMMENT '邮政编码（快照）',
  `status` varchar(32) NOT NULL DEFAULT '待付款' COMMENT '订单状态: 待付款, 已付款, 已发货, 已完成, 已取消, 已评价[reference:15]',
  `star_rating` int DEFAULT NULL COMMENT '评分(1-5)',
  `remarks` varchar(255) NOT NULL DEFAULT '' COMMENT '评价内容',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `idx_order_number` (`order_number`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_merchant_id` (`merchant_id`),
  KEY `idx_goods_id` (`goods_id`),
  KEY `idx_status` (`status`),
  CONSTRAINT `fk_orders_goods_id` FOREIGN KEY (`goods_id`) REFERENCES `second_hand_mall` (`second_hand_mall_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_orders_merchant_id` FOREIGN KEY (`merchant_id`) REFERENCES `sellers` (`seller_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_orders_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=221 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='订单表';
/*!40101 SET character_set_client = @saved_cs_client */;

