--
-- Table structure for table `second_hand_mall`
--

DROP TABLE IF EXISTS `second_hand_mall`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `second_hand_mall` (
  `second_hand_mall_id` int NOT NULL AUTO_INCREMENT COMMENT '商品ID，主键',
  `seller_id` int NOT NULL COMMENT '卖家ID (关联sellers.seller_id)',
  `category_id` int NOT NULL COMMENT '分类ID (关联categories.category_id)',
  `title` varchar(125) NOT NULL COMMENT '商品标题',
  `description` varchar(255) DEFAULT NULL COMMENT '商品简短描述',
  `content` longtext COMMENT '商品详情 (正文)',
  `price` decimal(10,2) NOT NULL COMMENT '售价',
  `price_ago` decimal(10,2) DEFAULT NULL COMMENT '原价',
  `inventory` int NOT NULL DEFAULT '1' COMMENT '库存数量',
  `hits` int NOT NULL DEFAULT '0' COMMENT '点击数',
  `recommend` int DEFAULT '0' COMMENT '智能推荐权重',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '商品状态 (1:上架, 0:下架, 2:已售)[reference:9]',
  `cover_img` text COMMENT '封面图URL',
  `img_1` text COMMENT '主图1',
  `img_2` text COMMENT '主图2',
  `img_3` text COMMENT '主图3',
  `img_4` text COMMENT '主图4',
  `img_5` text COMMENT '主图5',
  `remarks` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`second_hand_mall_id`),
  KEY `idx_seller_id` (`seller_id`),
  KEY `idx_category_id` (`category_id`),
  KEY `idx_status` (`status`),
  KEY `idx_price` (`price`),
  CONSTRAINT `fk_mall_category_id` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_mall_seller_id` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`seller_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='二手商品表';
/*!40101 SET character_set_client = @saved_cs_client */;

