--
-- Table structure for table `sellers`
--

DROP TABLE IF EXISTS `sellers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sellers` (
  `seller_id` int NOT NULL AUTO_INCREMENT COMMENT '卖家ID，主键',
  `user_id` int NOT NULL COMMENT '关联用户ID (users.user_id)',
  `seller_number` varchar(64) NOT NULL COMMENT '卖家编号',
  `seller_gender` varchar(10) DEFAULT NULL COMMENT '卖家性别',
  `seller_age` int DEFAULT NULL,
  `seller_school` varchar(64) DEFAULT NULL COMMENT '卖家学校',
  `seller_address` varchar(255) DEFAULT NULL,
  `seller_birthday` date DEFAULT NULL COMMENT '卖家生日',
  `brief_introduction` text COMMENT '卖家简介',
  `examine_state` varchar(16) NOT NULL DEFAULT '待审核' COMMENT '审核状态',
  `credit_score` int DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`seller_id`),
  KEY `idx_user_id` (`user_id`),
  CONSTRAINT `fk_sellers_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='卖家信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sellers`
--

