DROP TABLE IF EXISTS `sign_in_score`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sign_in_score` (
  `sign_in_score_id` int NOT NULL AUTO_INCREMENT COMMENT '签收评分ID，主键',
  `order_number` varchar(64) NOT NULL COMMENT '订单编号 (关联orders.order_number)',
  `purchase_user` int NOT NULL COMMENT '购买用户ID (users.user_id)',
  `business` int NOT NULL COMMENT '商家ID (sellers.seller_id)',
  `purchase_goods` varchar(64) NOT NULL COMMENT '购买商品名称（快照）',
  `commodity_price` decimal(10,2) NOT NULL COMMENT '商品价格（快照）',
  `sign_in_status` varchar(64) NOT NULL DEFAULT '待签收' COMMENT '签收状态',
  `star_rating` tinyint(1) DEFAULT NULL COMMENT '星级评分 (1-5)',
  `remarks` longtext COMMENT '评价备注',
  `recommend` int DEFAULT '0' COMMENT '智能推荐',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`sign_in_score_id`),
  KEY `idx_order_number` (`order_number`),
  KEY `idx_purchase_user` (`purchase_user`),
  KEY `idx_business` (`business`),
  CONSTRAINT `fk_sign_business_id` FOREIGN KEY (`business`) REFERENCES `sellers` (`seller_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_sign_user_id` FOREIGN KEY (`purchase_user`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='签收评分表';
/*!40101 SET character_set_client = @saved_cs_client */;

