DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `user_id` int NOT NULL AUTO_INCREMENT COMMENT '用户ID，主键',
  `username` varchar(64) NOT NULL COMMENT '用户名，用于登录',
  `password` varchar(255) NOT NULL COMMENT '密码（建议存储哈希值）[reference:5]',
  `email` varchar(125) DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(13) DEFAULT NULL COMMENT '手机号',
  `gender` varchar(10) DEFAULT NULL COMMENT '性别',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像URL',
  `role` enum('admin','seller','buyer') NOT NULL DEFAULT 'buyer' COMMENT '用户角色[reference:6]',
  `examine_state` varchar(16) DEFAULT '未审核' COMMENT '审核状态（卖家需审核）',
  `recommend` int DEFAULT '0' COMMENT '智能推荐权重',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `idx_username` (`username`),
  UNIQUE KEY `idx_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户信息表';
